const childKeys = {
  BinaryExpression: ["left", "right"],
  IfStatement: ["test", "consequent", "alternate"],
  Identifier: [],
};

const children = (n) =>
  (childKeys[n.type] ?? []).map((k) => n[k]).filter(Boolean);

function walk(node, visit) {
  visit(node);
  for (const c of children(node)) walk(c, visit);
}
